import csv, collections
rows = list(csv.DictReader(open('alerts_2026-09.csv')))
print(len(rows))
c = collections.Counter((r['service'], r['severity']) for r in rows)
svcs = {r['service'] for r in rows}; sevs = {r['severity'] for r in rows}
print(sorted(svcs)); print(sorted(sevs))
owners = {r['service'] for r in csv.DictReader(open('service_owners.csv'))}
print('unknown services', svcs - owners, 'unused owners', owners - svcs)
print('override hits', sum(v for (s, v2), v in c.items() if s in {'payments','ledger'} and v2 in {'sev1','sev2'}))
for k in sorted(c):
    if k[0] in {'payments','ledger'}: print(k, c[k])
